from __future__ import annotations
from collections import Counter
from .canonical import digest_object

def summary(run_id,classification_id,identities,ambiguities,aliases,collisions,locators,consumers):
    obj={'schema_version':'1.0.0','phase_id':'LCM-03','identity_run_id':run_id,'classification_id':classification_id,'claim_ceiling':'IDENTITY_AND_LOCATOR_REFERENCE_ONLY','active_candidate_count':len(identities)+len(ambiguities),'identity_candidate_count':len(identities),'identity_ambiguity_count':len(ambiguities),'identity_kind_counts':dict(sorted(Counter(x['identity_kind'] for x in identities).items())),'identity_status_counts':dict(sorted(Counter(x['identity_status'] for x in identities).items())),'alias_record_count':len(aliases),'resolvable_alias_count':sum(x['resolution_status']=='RESOLVABLE' for x in aliases),'ambiguous_alias_record_count':sum(x['resolution_status']=='AMBIGUOUS_BLOCKED' for x in aliases),'alias_collision_count':len(collisions),'locator_record_count':len(locators),'consumer_record_count':len(consumers),'all_active_candidates_identity_or_ambiguity':len(identities)+len(ambiguities)>0,'identity_ids_unique':len({x['identity_id'] for x in identities})==len(identities),'canonical_path_materialized_count':sum(x['canonical_path_materialized'] for x in locators),'source_move_performed':False,'source_delete_performed':False,'semantic_refactor_performed':False,'merge_performed':False,'cutover_performed':False,'human_semantic_approval_claimed':False,'runtime_authority_created':False,'live_order_authority_created':False,'capital_authority_created':False,'summary_digest':None}
    obj['summary_digest']=digest_object(obj,'summary_digest');return obj
